<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Services;
use RuntimeException;
final class TourismImageUploadService{private const MAX_BYTES=5*1024*1024;private const MIMES=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];public function store(array $file,string $category):string{$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($error!==UPLOAD_ERR_OK)throw new RuntimeException('Tourism image upload failed.');$tmp=(string)($file['tmp_name']??'');$size=(int)($file['size']??0);if($tmp===''||!is_uploaded_file($tmp)||$size<=0||$size>self::MAX_BYTES)throw new RuntimeException('Tourism image must be between 1 byte and 5 MB.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($tmp);if(!is_string($mime)||!isset(self::MIMES[$mime])||@getimagesize($tmp)===false)throw new RuntimeException('Only valid JPG, PNG and WebP images are allowed.');$root=dirname(__DIR__,4);$rel='uploads/tourism/'.$category;$dir=$root.'/public/'.$rel;if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Unable to create tourism image directory.');$fileName=bin2hex(random_bytes(16)).'.'.self::MIMES[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$fileName))throw new RuntimeException('Unable to save tourism image.');return $rel.'/'.$fileName;}public function delete(?string $path):void{$path=trim((string)$path);if($path==='')return;$root=dirname(__DIR__,4);$public=realpath($root.'/public');$file=realpath($root.'/public/'.ltrim($path,'/'));if($public===false||$file===false||!is_file($file))return;$prefix=rtrim($public,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR;if(str_starts_with($file,$prefix))@unlink($file);}}
